    ArrayUtils.reverse(array, 0, 3);
    assertTrue(array[0]);
    assertFalse(array[1]);
    assertFalse(array[2]);
    // a range
    array = new boolean[] { false, false, true };
    ArrayUtils.reverse(array, 0, 2);
    assertFalse(array[0]);
    assertFalse(array[1]);
    assertTrue(array[2]);
    // a range with a negative start
    array = new boolean[] { false, false, true };
    ArrayUtils.reverse(array, -1, 3);
    assertTrue(array[0]);
    assertFalse(array[1]);
    assertFalse(array[2]);
    // a range with a large stop index
    array = new boolean[] { false, false, true };
    ArrayUtils.reverse(array, -1, array.length + 1000);
    assertTrue(array[0]);
    assertFalse(array[1]);
    assertFalse(array[2]);
    // null
    array = null;
    ArrayUtils.reverse(array, 0, 3);
    assertNull(array);
}

