    assertFalse(notc.contains(ae));
    assertFalse(notc.contains(all));
    assertFalse(notc.contains(allbutfirst));
    assertTrue(notbd.contains(a));
    assertFalse(notbd.contains(b));
    assertFalse(notbd.contains(c));
