    assertEquals(1, f.getNumerator());
    assertEquals(2, f.getDenominator());
    f = Fraction.getReducedFraction(15, 10);
    assertEquals(3, f.getNumerator());
    assertEquals(2, f.getDenominator());
    f = Fraction.getReducedFraction(121, 22);
    assertEquals(11, f.getNumerator());
    assertEquals(2, f.getDenominator());
