    for (int i = 1; i <= 100; i++) {
        // denominator
        for (int j = 1; j <= i; j++) {
            // numerator
            f = Fraction.getFraction((double) j / (double) i);
            f2 = Fraction.getReducedFraction(j, i);
            assertEquals(f2.getNumerator(), f.getNumerator());
            assertEquals(f2.getDenominator(), f.getDenominator());
