    assertArrayEquals(foo, StringUtils.stripAll(fooSpace));
    assertNull(StringUtils.stripAll(null, null));
    assertArrayEquals(foo, StringUtils.stripAll(fooSpace, null));
    assertArrayEquals(foo, StringUtils.stripAll(fooDots, "."));
}

