    assertTrue(watch.isStarted());
    assertFalse(watch.isSuspended());
    assertFalse(watch.isStopped());
    watch.suspend();
    assertTrue(watch.isStarted());
    assertTrue(watch.isSuspended());
    assertFalse(watch.isStopped());
